// Minimal implementation of "Cosmic Cleaner" game
// Canvas id: "game"
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas #game not found');
  const ctx = canvas.getContext('2d');
  const W = (canvas.width = canvas.clientWidth || 800);
  const H = (canvas.height = canvas.clientHeight || 600);

  // Ship configuration
  const ship = { x: W / 2, y: H - 60, w: 30, h: 40, speed: 4, cargo: 0, alive: true };
  let vacuumOn = false;
  const keys = {};

  // Simple asteroid/debris generator
  const objects = [];
  function spawn() {
    const size = Math.random() * 20 + 10;
    const isDebris = Math.random() < 0.4; // 40% are collectable debris
    objects.push({
      x: Math.random() * (W - size),
      y: -size,
      w: size,
      h: size,
      speed: 1 + Math.random() * 2,
      debris: isDebris,
    });
  }
  setInterval(spawn, 800);

  // Input handling
  window.addEventListener('keydown', e => {
    keys[e.key] = true;
    if (e.key === ' ') vacuumOn = true;
    if (e.key === 'd') ship.cargo = 0; // cargo‑dump mini‑game shortcut
  });
  window.addEventListener('keyup', e => {
    keys[e.key] = false;
    if (e.key === ' ') vacuumOn = false;
  });

  // Collision helpers
  function rectIntersect(a, b) {
    return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
  }

  // Main loop
  function update() {
    if (!ship.alive) return; // stop updating after death
    // Move ship
    if (keys.ArrowLeft) ship.x -= ship.speed;
    if (keys.ArrowRight) ship.x += ship.speed;
    if (keys.ArrowUp) ship.y -= ship.speed;
    if (keys.ArrowDown) ship.y += ship.speed;
    // Keep within bounds
    ship.x = Math.max(0, Math.min(W - ship.w, ship.x));
    ship.y = Math.max(0, Math.min(H - ship.h, ship.y));

    // Update objects
    for (let i = objects.length - 1; i >= 0; i--) {
      const o = objects[i];
      o.y += o.speed;
      // Collision with ship
      if (rectIntersect(ship, o)) {
        if (o.debris && vacuumOn) {
          ship.cargo++;
          objects.splice(i, 1);
          continue;
        } else if (!o.debris) {
          // asteroid hit – ship destroyed
          ship.alive = false;
          break;
        }
      }
      // Remove off‑screen objects
      if (o.y > H) objects.splice(i, 1);
    }
    // Overload check
    if (ship.cargo > 10) ship.alive = false;
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);
    // Draw ship
    ctx.fillStyle = ship.alive ? '#0ff' : '#f00';
    ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
    // Vacuum beam visual
    if (vacuumOn) {
      ctx.strokeStyle = '#0ff';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(ship.x + ship.w / 2, ship.y);
      ctx.lineTo(ship.x + ship.w / 2, 0);
      ctx.stroke();
    }
    // Draw objects
    objects.forEach(o => {
      ctx.fillStyle = o.debris ? '#ff0' : '#888';
      ctx.fillRect(o.x, o.y, o.w, o.h);
    });
    // HUD
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + ship.cargo, 10, 20);
    if (!ship.alive) ctx.fillText('GAME OVER', W / 2 - 50, H / 2);
  }

  function loop() {
    update();
    draw();
    requestAnimationFrame(loop);
  }
  loop();
})();
